"""Phase 6D: docs/phase6_report_tables.md from results/phase6/*.json (and the read-only Phase 5 handoff).  Every number is read, not typed."""
from _common import RES, P5, ROOT, np, MSUBS, CASES, SHORT
import json

j = json.load(open(RES / "6a_subarrays.json")); jb = json.load(open(RES / "6b_robustness.json")); p5 = json.load(open(P5 / "phase5_handoff.json"))
best = jb["best"]; BM = str(best["msub"]); BC = best["case"]
r30 = lambda M: j["30"][str(M)]
T = []


def tab(title, header, rows, note=None):
    T.append(f"### {title}\n")
    T.append("| " + " | ".join(header) + " |"); T.append("|" + "|".join(["---"] * len(header)) + "|")
    for r in rows: T.append("| " + " | ".join(str(x) for x in r) + " |")
    if note: T.append(f"\n{note}")
    T.append("")


def fmt(x, n=3):
    if x is None: return "n/a"
    if isinstance(x, float) and np.isinf(x): return "-inf" if x < 0 else "inf"
    if isinstance(x, float) and np.isnan(x): return "nan"
    return f"{x:.{n}f}"


T.append("# Phase 6 report tables\n\nGenerated by `experiments/phase6/6d_tables.py` from `results/phase6/6a_subarrays.json`, `6b_robustness.json` and the read-only Phase 5 handoff. "
         "All beam numbers are over mask_common (0.231-0.268, domain-limited), res 30 unless stated. \"Trimmed PhC\" = phase-intercept-trimmed PhC (never ideal TTD); in Phase 6 it is re-trimmed to the *required* step for each Msub unless labeled \"P4 H_trim as is\".\n")

# A
rows = []
for M in MSUBS:
    a = j["arch"][str(M)]
    rows.append([M, a["n_el"], "lambda0/2 = " + fmt(a["d_e"], 4) + " a", f"{a['subarray_pitch_over_lambda0']:.1f} lambda0 = {fmt(a['subarray_pitch'], 3)} a", f"{fmt(a['tau_req'], 4)} a ({fmt(a['req_cycles_f0'], 3)} cyc)",
                 f"{fmt(a['phc_cycles_f0'], 4)} cyc", fmt(a["rho"], 4), f"{100 * a['mismatch_rel']:+.2f} %", f"{a['mismatch_cycles']:+.4f}", fmt(a["aperture_lambda0"], 1)])
b = j["arch_B"]
tab("TABLE A - architecture definitions and delay match", ["Msub", "elements", "element spacing", "subarray spacing", "required step tau_req", "PhC step", "rho = tau_PhC/tau_req", "relative mismatch", "f0 (tau_PhC - tau_req) [cycle]", "aperture N d_e [lambda0]"], rows,
    f"Case A (Phase 5): d = {fmt(p5['setup']['d_over_lambda0'], 3)} lambda0, 4 elements, element-level PhC, step {fmt(p5['setup']['delay_quantum_cycles'], 4)} cycle. Case B (ideal reference only): d = lambda0/2, required step lambda0/4 = {fmt(b['tau_half'], 4)} a = {fmt(b['tau_half_cycles'], 3)} cycle; **tau_PhC / tau_half = {fmt(b['ratio_phc_over_half'], 4)}**. "
    "Msub = 1 is the hybrid (Case C: element-level PhC + constant phase) array.")

# B
rows = []
for M in MSUBS:
    r = r30(M)
    for k in ("fixed", "ideal_elem", "ideal_sub", "raw", "trim", "trim_p4"):
        rows.append([M, SHORT[k], fmt(r["max_abs_err"][k], 3), fmt(r["rms_err"][k], 3), fmt(r["spread_ptp"][k], 3), fmt(r["R_squint"][k], 3), fmt(r["R_squint_spread"][k], 3), fmt(r["vs_ideal_elem_max"][k], 3),
                     fmt(r["gain_min"][k], 3), fmt(r["strongest_db_max"][k], 2), fmt(r["grating_db_max"][k], 2), r["n3db_max"][k], "yes" if r["ambiguity"][k] else "no", f"{r['window_use_max_frac'][k]:.2f}"])
tab("TABLE B - beam metrics, Msub = 1, 2, 4, 8 (res 30)", ["Msub", "case", "max abs err [deg]", "RMS err [deg]", "ptp [deg]", "R_squint", "R_squint,spread", "max abs(theta - theta_ideal elem.) [deg]", "min peak power", "strongest other lobe [dB]", "strongest replica lobe [dB]", "max lobes within 3 dB", "ambiguity (>-10 dB)", "window use"], rows,
    "R_squint = max abs(theta - 30) / max abs(theta_fixed - 30) of the same array (includes absolute offset); R_squint,spread removes theta(f0). Strongest replica lobe = level at the analytic subarray-level grating positions (-inf: none visible). Window use near 1 means the lobe left the tracking window (tracking not meaningful). "
    "Tracking criterion per Msub: max abs err <= tol_pt = " + ", ".join(f"{M}: {fmt(r30(M)['tol_pt'], 3)} deg" for M in MSUBS) + ".")

# C
p = p5["30"]; rb = r30(BM)
def row(name, spacing, nel, mx, sp, gl, hp, ap, trims):
    return [name, spacing, nel, mx, sp, gl, hp, ap, trims]
rows = [row("Phase 5 fixed phase (reference)", "1.96 lambda0", 4, fmt(p["max_abs_err"]["fixed"], 3), "-", fmt(p["strongest_db_max"]["fixed"], 2), fmt(p["hpbw_low_f0_high"]["fixed"][1], 2), fmt(4 * p5["setup"]["d_over_lambda0"], 2), "none"),
        row("Phase 5 element-level raw PhC", "1.96 lambda0", 4, fmt(p["max_abs_err"]["raw"], 3), fmt(p["R_squint_spread"]["raw"], 3), fmt(p["strongest_db_max"]["raw"], 2), fmt(p["hpbw_low_f0_high"]["raw"][1], 2), fmt(4 * p5["setup"]["d_over_lambda0"], 2), "none (offset up to 2.7 rad)"),
        row("Phase 5 element-level trimmed PhC", "1.96 lambda0", 4, fmt(p["max_abs_err"]["trim"], 3), fmt(p["R_squint_spread"]["trim"], 3), fmt(p["strongest_db_max"]["trim"], 2), fmt(p["hpbw_low_f0_high"]["trim"][1], 2), fmt(4 * p5["setup"]["d_over_lambda0"], 2), "3 constants (per channel)"),
        row(f"Phase 6 Msub={BM} {SHORT[BC]} (best)", "0.5 lambda0 (subarray pitch " + fmt(j['arch'][BM]['subarray_pitch_over_lambda0'], 1) + " lambda0)", j["arch"][BM]["n_el"], fmt(rb["max_abs_err"][BC], 3), fmt(rb["R_squint_spread"][BC], 3), fmt(rb["strongest_db_max"][BC], 2), fmt(rb["hpbw_low_f0_high"][BC][1], 2), fmt(j["arch"][BM]["aperture_lambda0"], 2), "3 constants (per subarray channel) + fixed intra-subarray phases"),
        row(f"Phase 6 Msub={BM} fixed phase (reference)", "0.5 lambda0", j["arch"][BM]["n_el"], fmt(rb["max_abs_err"]["fixed"], 3), "-", fmt(rb["strongest_db_max"]["fixed"], 2), fmt(rb["hpbw_low_f0_high"]["fixed"][1], 2), fmt(j["arch"][BM]["aperture_lambda0"], 2), "none")]
tab("TABLE C - Phase 5 sparse element-level array vs best Phase 6 subarray architecture", ["configuration", "element spacing", "elements", "max abs err [deg]", "R_squint,spread", "strongest other lobe (over band) [dB]", "HPBW at f0 [deg]", "aperture [lambda0]", "trims"], rows,
    f"Phase 5 strongest other lobe is the grating lobe (equal strength). Phase 6 strongest replica (grating) lobe, best: {fmt(rb['grating_db_max'][BC], 2)} dB; strongest other lobe is then an ordinary sidelobe ({fmt(rb['strongest_db_max'][BC], 2)} dB; uniform-array first sidelobe is -13.3 dB).")

# D
rows = []
for M in MSUBS:
    r = r30(M)
    for k in ("fixed", "ideal_elem", "trim", "raw"):
        for ii, lab in enumerate(("low 0.231", "f0 0.2495", "high 0.268")):
            rows.append([M, SHORT[k], lab, fmt(r["err_low_f0_high"][k][ii], 3), fmt(r["gain_low_f0_high"][k][ii], 3), fmt(r["hpbw_low_f0_high"][k][ii], 2), fmt(r["strongest_db_low_f0_high"][k][ii], 2),
                         fmt(r["strongest_theta_low_f0_high"][k][ii], 1), fmt(r["grating_db_low_f0_high"][k][ii], 2), r["n_replicas_low_f0_high"][k][ii]])
tab("TABLE D - low / f0 / high pattern metrics (res 30)", ["Msub", "case", "frequency", "pointing error [deg]", "peak power", "HPBW [deg]", "strongest other lobe [dB]", "its angle [deg]", "strongest replica lobe [dB]", "visible replicas"], rows)

# E-G
def sens_rows(kind, extra=None):
    d = {r["level"]: r for r in jb["deterministic"].get(kind, [])}
    out = []
    for m in jb["monte_carlo"][kind]:
        dd = d.get(m["level"])
        out.append([m["level"], fmt(m["max_err"]["median"], 3), fmt(m["max_err"]["p95"], 3), fmt(m["max_err"]["worst"], 3), fmt(m["rms_err"]["median"], 3), fmt(m["gain_loss_db"]["p95"], 3), fmt(m["strongest_db"]["p95"], 2), fmt(m["r_squint"]["p95"], 3),
                    fmt(dd["shift_max"], 4) if dd else "-", fmt(dd["pred_max"], 4) if dd and "pred_max" in dd else "-"])
    return out
H = ["half-width", "max abs err median [deg]", "max abs err P95", "max abs err worst", "RMS median", "peak-power loss P95 [dB]", "strongest lobe P95 [dB]", "R_squint P95", "deterministic ramp: numeric max shift [deg]", "first-order prediction [deg]"]
tab("TABLE E - constant phase-trim error sensitivity (Monte Carlo, uniform +-a deg per channel; deterministic ramp +-a end to end)", ["a [deg]"] + H[1:], sens_rows("phase"),
    f"Best architecture: Msub = {BM}, {SHORT[BC]}; nominal max abs err = {fmt(jb['nominal_max_err_deg'], 3)} deg. Peak-power loss = -min over the band of 10 log10(p/p_nom) (positive = loss; negative = the peak power rose); P95 is the bad tail.")
tab("TABLE F1 - group-delay error, uncalibrated (exp(+i 2 pi f dtau); e_q uniform +-e of q tau_PhC)", ["e [%]"] + H[1:], sens_rows("delay_uncal"))
tab("TABLE F2 - group-delay error, calibrated at f0 (pure slope error exp(+i 2 pi (f-f0) dtau))", ["e [%]"] + H[1:], sens_rows("delay_cal"))
tab("TABLE F4 - group-delay error scaled to the absolute device delay (N_q + 6) tau_PhC, calibrated at f0 (intercept re-trimmed; the realistic reading of a length error)", ["e [%]"] + H[1:], sens_rows("delay_abs_cal"))
tab("TABLE F3 - group-delay error scaled to the absolute device delay (N_q + 6) tau_PhC, uncalibrated (sensitivity)", ["e [%]"] + H[1:], sens_rows("delay_abs_uncal"),
    "The relative error here is applied to the full device delay (about 55 a/c), not to the relative delay q tau_PhC; this is the pessimistic reading of a length error with no calibration of the trim.")
tab("TABLE G - amplitude-error sensitivity (uniform +-A dB per channel; deterministic ramp +-A end to end)", ["A [dB]", "max abs err median [deg]", "max abs err P95", "max abs err worst", "RMS median", "peak-power loss P95 [dB]", "efficiency loss P95 [dB] (fixed input power)", "efficiency loss worst [dB]", "strongest lobe P95 [dB]", "R_squint P95", "deterministic ramp: max shift [deg]", "deterministic ramp: min peak power loss [dB]"],
    [[m["level"], fmt(m["max_err"]["median"], 3), fmt(m["max_err"]["p95"], 3), fmt(m["max_err"]["worst"], 3), fmt(m["rms_err"]["median"], 3), fmt(m["gain_loss_db"]["p95"], 3), fmt(m["eff_loss_db"]["p95"], 3), fmt(m["eff_loss_db"]["worst"], 3), fmt(m["strongest_db"]["p95"], 2), fmt(m["r_squint"]["p95"], 3),
      fmt(d["shift_max"], 4), fmt(d["gain_loss_db"], 3)] for m, d in zip(jb["monte_carlo"]["amp"], jb["deterministic"]["amp"])],
    "Efficiency loss (post hoc diagnostic) divides the peak power by the sum of |G_q|^2, i.e. holds the total input power fixed so a pure level change is not counted as a gain.")

# H
rows = []
for m in jb["monte_carlo"]["combined"]:
    s = m["spec"]
    for key, nm in (("max_err", "max abs err [deg]"), ("rms_err", "RMS err [deg]"), ("gain_loss_db", "peak-power loss, worst f [dB]"), ("eff_loss_db", "efficiency loss at fixed input power [dB]"), ("strongest_db", "strongest other lobe [dB]"), ("r_squint", "R_squint")):
        rows.append([m["level"], f"{s['eps_deg']:g} deg / {100 * s['delay_frac']:g} % / {s['amp_db']:g} dB", nm, fmt(m[key]["median"], 3), fmt(m[key]["p90"], 3), fmt(m[key]["p95"], 3), fmt(m[key]["worst"], 3)])
tab("TABLE H - Monte Carlo percentiles, combined phase + delay + amplitude errors (1000 samples, seed 20261010)", ["level", "(phase, delay, amplitude)", "metric", "median", "P90", "P95", "worst"], rows,
    f"Gate test (criterion 13): P95 max abs err at L2 = {fmt(jb['combined_L2_p95_max_err'], 3)} deg (limit 1.0): {'passed' if jb['combined_L2_ok'] else 'FAILED'}. Single-parameter percentile tables are Tables E-G.")

# I
def b(kind, st, lim):
    v = jb["budget"][kind][st][lim]
    return "unattainable (nominal exceeds limit)" if v is None else (">" + fmt(max(m['level'] for m in jb['monte_carlo'][kind]), 3) + " (beyond the swept range)" if v == float("inf") else fmt(v, 3))
rows = []
for kind, nm, un in (("phase", "constant phase-trim error half-width", "deg"), ("delay_uncal", "delay error, uncalibrated, of q tau_PhC", "%"), ("delay_cal", "delay error, calibrated at f0, of q tau_PhC", "%"),
                      ("delay_abs_uncal", "delay error, uncalibrated, of absolute device delay", "%"), ("delay_abs_cal", "delay error, calibrated at f0, of absolute device delay", "%"), ("amp", "amplitude error half-width", "dB")):
    rows.append([nm, un, b(kind, "median", "0.5"), b(kind, "p95", "0.5"), b(kind, "median", "1.0"), b(kind, "p95", "1.0")])
tab("TABLE I - system-level tolerance estimates (independent uniform errors on all channels)", ["error source", "unit", "median max abs err <= 0.5 deg", "P95 <= 0.5 deg", "median <= 1.0 deg", "P95 <= 1.0 deg"], rows,
    "Largest half-width (linear interpolation of the Monte Carlo curve) for which the statistic of the max pointing error over mask_common, **including the nominal error**, stays below the limit. System-level tolerance estimates from the Phase 4 transfer functions; not fabrication specifications (no fabrication model used). "
    f"Delay equivalents: 1 % of tau_PhC = {0.01 * 3.9323:.4f} a/c = {0.01 * 0.98111:.4f} cycle at f0 (q = 1).")

# J
rows = []
rb4 = j["res_check"][BM]
tol3 = rb4[BC]["tol_third"]
for M in MSUBS:
    for k in ("trim", "raw", "trim_p4"):
        c = j["res_check"][str(M)][k]
        ok = (c["max_dtheta_deg"] <= c["tol_third"] and c["d_max_abs_err"] <= c["tol_third"] and c["d_R_squint"] <= 0.02 and c["d_gain"] <= 0.02 and c["d_strongest_db"] <= 0.5)
        rows.append([M, SHORT[k], fmt(c["max_dtheta_deg"], 4), fmt(c["d_max_abs_err"], 4), fmt(c["d_R_squint"], 4), fmt(c["d_gain"], 4), fmt(c["d_strongest_db"], 3), fmt(c["tol_third"], 3), "pass" if ok else "outside"])
tab("TABLE J - res 30 vs res 40 sensitivity (criterion 12: max abs d(theta), d(max err) <= tol_pt/3; d R_squint <= 0.02; d power <= 0.02; d strongest lobe <= 0.5 dB)", ["Msub", "case", "max abs(theta30 - theta40) [deg]", "abs d(max err) [deg]", "abs d(R_squint)", "max abs d(peak power)", "max abs d(strongest lobe) [dB]", "tol_pt/3 [deg]", "verdict"], rows,
    f"The declared check applies to the best architecture (Msub = {BM}, {SHORT[BC]}). Other rows are diagnostics. res-40 channels are re-trimmed from the res-40 raw data.")

# K quantization
rows = [[r["msub"], fmt(r["rho"], 3), fmt(r["max_err"], 3), fmt(r["spread"], 3), fmt(r["R_squint"], 3), fmt(r["R_spread"], 3), fmt(r["strongest_db_max"], 2), fmt(r["grating_db_max"], 2)] for r in jb["quantization_scan"]]
tab("TABLE K - period quantization: actual retrimmed PhC channels (k = 1 period per step) for every Msub", ["Msub", "rho", "max abs err [deg]", "ptp [deg]", "R_squint", "R_squint,spread", "strongest other lobe [dB]", "strongest replica lobe [dB]"], rows,
    "Fractional-period devices are not simulated; the continuous-rho curve (Figure 6_11) is an ideal-delay model of that hypothetical technology. Msub = 8 with k = 2 periods per step (rho = 0.981 again) would need a channel family with 2-period increments, which was not simulated.")
(ROOT / "docs" / "phase6_report_tables.md").write_text("\n".join(T))
print("tables written", len(T))
